package com.coworkhub.entity;
import jakarta.persistence.*;
@Entity @Table(name="members",uniqueConstraints={@UniqueConstraint(columnNames="document_number"),@UniqueConstraint(columnNames="email")}) public class Member { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(name="document_number",nullable=false,unique=true) public String documentNumber; @Column(nullable=false) public String fullName; @Column(nullable=false,unique=true) public String email; @Enumerated(EnumType.STRING) public Enums.MemberStatus status=Enums.MemberStatus.ACTIVE; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="plan_id",nullable=false) public MembershipPlan plan; @com.fasterxml.jackson.annotation.JsonIgnore @OneToOne(mappedBy="member") public UserAccount account; public Member(){} }
